it('counts the client’s deadlines as the Deadlines panel lists them, the dates on the client record included', () => {
  const db = setup()
  // A VAT date only on the client record: on the Deadlines panel, so in the figures above it too.
  db.exec(`UPDATE clients SET vat_due = '${local(3)}' WHERE ref = 'C1'`)
  const o = clientFile(db, partner, 'C1').overview
  const listed = openDeadlines(db, partner, { clientRef: 'C1', withinDays: 3650 })
  expect([o.openDeadlines, o.overdueDeadlines, o.nextDueDate]).toEqual([listed.length, listed.filter((d) => d.days < 0).length, local(3)])
  expect(o.openDeadlines).toBe(3)
})
